/* Unlimited distinct highlight suggestions and complete, gap-free video parts. */
let videoDuration=0,durationVerified=false;
function showReadyParts(id,parts){
 for(const n of parts){if(individual.querySelector('[data-part="'+n+'"]'))continue;
 const row=document.createElement('div');row.dataset.part=n;const label=document.createElement('span');label.textContent='Part '+n+' · Ready';const preview=document.createElement('button');preview.textContent='Preview';preview.onclick=()=>showRendered({previewUrl:'/api/parts/'+id+'/'+n+'/preview'});const link=document.createElement('a');link.textContent='Download MP4';link.href='/api/parts/'+id+'/'+n+'/download';row.append(label,preview,link);individual.append(row)}individual.hidden=false;
}
const modeBox=document.createElement('div');modeBox.className='clip-mode';modeBox.innerHTML='<label for="clipMode">What would you like to make?</label><select id="clipMode"><option value="highlights">Find all highlights</option><option value="whole">Split entire video into parts</option></select><p id="modeHint">Find as many distinct moments as the video supports. No three-clip limit.</p>';
document.querySelector('.analysis-options').before(modeBox);
const splitControls=document.createElement('div');splitControls.className='clip-mode';splitControls.hidden=true;splitControls.innerHTML='<label for="splitMethod">Split the whole video by</label><select id="splitMethod"><option value="count">Number of clips</option><option value="length">Length of each clip</option></select><label for="partCount">How many separate clips?</label><input id="partCount" type="number" min="1" max="1000" step="1" value="10"><p id="splitSummary">Choose a number. Every second is included, in order.</p>';modeBox.after(splitControls);
const individual=document.createElement('div');individual.className='individual-clips';individual.hidden=true;document.querySelector('.moments-intro').before(individual);
function splitCount(duration,count,cues){if(!Number.isInteger(count)||count<1||count>Math.min(1000,Math.floor(duration)))throw Error('Choose a whole number from 1 to '+Math.min(1000,Math.floor(duration))+'. Each clip needs at least one second.');return Array.from({length:count},(_,i)=>{const start=duration*i/count,end=duration*(i+1)/count;return {start,end,text:cues.filter(c=>c.start<end&&c.end>start).map(c=>c.text).join(' '),title:'Part '+String(i+1).padStart(2,'0')+' · '+stamp(start)+'–'+stamp(end),score:0,reason:'Consecutive section of the original video. Nothing skipped.',type:'In order'}})}

$('clipLength').insertAdjacentHTML('afterbegin','<option value="15">15 seconds</option>');
$('clipLength').insertAdjacentHTML('beforeend','<option value="90">90 seconds</option><option value="120">2 minutes</option><option value="180">3 minutes</option>');
const batchBtn=document.createElement('button');batchBtn.id='batchBtn';batchBtn.className='primary batch-export';batchBtn.textContent='Create all clips ↓';batchBtn.disabled=true;document.querySelector('.moments-intro').before(batchBtn);
const bundleLink=document.createElement('a');bundleLink.id='bundleDownload';bundleLink.className='primary batch-export';bundleLink.textContent='Download all clips (.zip) ↓';bundleLink.hidden=true;batchBtn.after(bundleLink);
const modeRender=render,modeBusy=setBusy,baseEdit=updateEdit,baseRequest=requestJSON;
requestJSON=async function(url,options){if(url==="/api/analyze"){videoDuration=0;durationVerified=false;bundleLink.hidden=true;individual.hidden=true;}const result=await baseRequest(url,options);if(url.startsWith('/api/jobs/')&&result.action==='batch'&&result.readyParts?.length)showReadyParts(result.id,result.readyParts);if(url.startsWith('/api/jobs/')&&result.action==='analyze'&&result.status==='complete'){videoDuration=result.result.duration;durationVerified=Boolean(result.result.durationExact);if(!result.result.cues.length)$('clipMode').value='whole';if(Number($('partCount').value)>Math.floor(videoDuration))$('partCount').value=Math.max(1,Math.floor(videoDuration));}return result};
setBusy=function(value){modeBusy(value);$('clipMode').disabled=value;$('splitMethod').disabled=value;$('partCount').disabled=value;$('sort').disabled=value||$('clipMode').value==='whole';batchBtn.disabled=value||!projectId||!state.clips.length;$('clipLength').disabled=value||($('clipMode').value==='whole'&&$('splitMethod').value==='count');};
render=function(){modeRender();const full=$('clipMode').value==='whole';$('clipLength').disabled=processing||(full&&$('splitMethod').value==='count');$('startTime').readOnly=full;$('endTime').readOnly=full;if(full){$('moments').querySelectorAll('.score').forEach(el=>el.hidden=true);$('sort').value='time';}$('sort').disabled=processing||full;batchBtn.textContent=`Create all ${state.clips.length||''} clips ↓`;batchBtn.disabled=processing||!projectId||!state.clips.length;$('analyzeBtn').disabled=processing||(!state.cues.length&&!videoDuration);};
function splitAll(duration,length,cues){if(!(length>0)||Math.ceil(duration/length)>1000)throw Error('Choose longer parts or split by number (up to 1,000 clips per batch).');const parts=[];for(let start=0;start<duration;start+=length){const end=Math.min(duration,start+length);const text=cues.filter(c=>c.start<end&&c.end>start).map(c=>c.text).join(' ');parts.push({start,end,text,title:`Part ${String(parts.length+1).padStart(2,'0')} · ${stamp(start)}–${stamp(end)}`,score:0,reason:'Consecutive section of the original video. Nothing skipped.',type:'In order'});}return parts;}
const highlightsWithoutLimit=findHighlights;
findHighlights=function(){if($('clipMode').value!=='whole')return highlightsWithoutLimit();try{const cues=$('transcript').value.trim()?parseTranscript($('transcript').value):[];const duration=state.demo?cues.at(-1)?.end:videoDuration;if(!state.demo&&!durationVerified)throw Error('Analyze the link again to verify the full video length before splitting it.');if(!(duration>0))throw Error('Add a video first.');state.cues=cues;state.clips=$('splitMethod').value==='count'?splitCount(duration,Number($('partCount').value),cues):splitAll(duration,Number($('clipLength').value),cues);$('splitSummary').textContent=state.clips.length+' separate clips, about '+(duration/state.clips.length).toFixed(1)+' seconds each. Every second included. Longer parts may exceed your destination’s upload limits.';state.selected=0;$('sort').value='time';$('analysisError').textContent='';render();return {count:state.clips.length,method:'Complete video, consecutive parts'}}catch(e){state.clips=[];state.selected=0;render();$('analysisError').textContent=e.message;throw e}};
updateEdit=function(){if($('clipMode').value!=='whole')return baseEdit();const c=selected();if(!c)return false;const start=Number($('startTime').value),end=Number($('endTime').value),duration=state.demo?state.cues.at(-1)?.end:videoDuration;if(!Number.isFinite(start)||!Number.isFinite(end)||start<0||end<=start||end>duration){$('editError').textContent='Choose a valid range within the video.';return false}c.start=start;c.end=end;c.title=$('clipTitle').value.trim()||c.title;c.text=state.cues.filter(x=>x.start<end&&x.end>start).map(x=>x.text).join(' ');$('editError').textContent='';return true};
function regenerate(){if(processing)return;bundleLink.hidden=true;individual.hidden=true;splitControls.hidden=$('clipMode').value!=='whole';$('partCount').hidden=$('splitMethod').value!=='count';splitControls.querySelector('label[for=partCount]').hidden=$('partCount').hidden;$('modeHint').textContent=$('clipMode').value==='whole'?'Every second, in order. The last part can be shorter. Part numbers are in the filenames, not on your video.':'Find as many distinct moments as the video supports. No three-clip limit.';if($('clipMode').value==='whole')$('sort').value='time';else $('sort').value='score';if(state.cues.length||videoDuration){try{findHighlights()}catch{}}}
$('splitMethod').onchange=regenerate;$('partCount').oninput=regenerate;$('partCount').onchange=regenerate;$('clipMode').onchange=regenerate;$('clipLength').onchange=regenerate;
batchBtn.onclick=async()=>{if(!projectId||processing||!state.clips.length)return;const clips=[...state.clips].sort((a,b)=>a.start-b.start).map(c=>({start:c.start,end:c.end,title:c.title}));setBusy(true);individual.replaceChildren();individual.hidden=true;bundleLink.hidden=true;$('analysisError').textContent='';showProgress(`Preparing ${clips.length} clips…`,1);$('jobDetail').textContent='Download each clip as soon as it finishes. The rest keep rendering; keep this page open.';try{const job=await requestJSON('/api/batch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({projectId,clips,style:state.style})});const result=await pollJob(job.id,57600);individual.replaceChildren();const heading=document.createElement('h3');heading.textContent='Your individual clips';individual.append(heading);clips.forEach((c,i)=>{const row=document.createElement('div');const label=document.createElement('span');label.textContent='Part '+(i+1)+' · '+stamp(c.start)+'–'+stamp(c.end);const preview=document.createElement('button');preview.textContent='Preview';preview.onclick=()=>showRendered({previewUrl:'/api/parts/'+job.id+'/'+(i+1)+'/preview'});const link=document.createElement('a');link.textContent='Download MP4';link.href='/api/parts/'+job.id+'/'+(i+1)+'/download';row.append(label,preview,link);individual.append(row)});individual.hidden=false;bundleLink.href=result.downloadUrl;bundleLink.hidden=false;showProgress(`All ${result.count} clips are ready`,100);$('jobDetail').textContent='Download separately below or get the ZIP. Numbered MP4s are in chronological order, with a clip-order file.';toast('Your clips are ready.')}catch(e){$('analysisError').textContent=e.message;showProgress('Batch could not finish',0)}finally{setBusy(false)}};
const resetDemo=$('demoBtn').onclick;$('demoBtn').onclick=()=>{videoDuration=0;durationVerified=false;resetDemo();regenerate()};
render();

const review=document.createElement('section');review.className='tiktok-review';review.innerHTML='<h3>TikTok clip review</h3><p>Choose a moment to check its opening and pacing.</p>';
document.querySelector('.score-note').after(review);
const reviewedRender=render;
render=function(){reviewedRender();const c=selected();review.replaceChildren();const title=document.createElement('h3');title.textContent='TikTok clip review';review.append(title);if(!c)return;
 const cues=state.cues.filter(x=>x.start<c.end&&x.end>c.start),opening=cues.filter(x=>x.start<c.start+6).map(x=>x.text).join(' '),words=c.text.trim()?c.text.trim().split(/\s+/).length:0,wpm=Math.round(words/(c.end-c.start)*60);
 const notes=[['First six seconds',opening||'No speech detected here. Check that the visuals give viewers a reason to stay.'],['Opening check',/\?|\b(why|how|imagine|mistake|secret|stop)\b/i.test(opening)?'Question or curiosity wording detected. Preview it to confirm the payoff matches.':'Make the topic and payoff clear immediately. Avoid an introduction that delays the interesting moment.'],['Speech pace',words?wpm+' words/minute (transcript estimate). '+(wpm>190?'Fast speech: check captions are readable.':'Preview for pauses and clear delivery.'):'No transcript available; review audio and visuals.'],['Ending',cues.at(-1)?.end>c.end+.05?'This part cuts through a caption segment. Whole-video splitting preserves every second but can divide sentences.':/[.!?]["\u201d\u2019\x27]?$/.test(c.text.trim())?'Transcript ends with punctuation. Check that the idea actually resolves.':'The thought may continue beyond this clip. Preview before posting.']];
 for(const [label,text] of notes){const p=document.createElement('p'),b=document.createElement('strong');b.textContent=label+': ';p.append(b,document.createTextNode(text));review.append(p)}
 const details=document.createElement('details');details.innerHTML='<summary>Quality &amp; reach guidance</summary><p>Exports use 1080 × 1920, the best available source up to 4K, source frame rate up to 60 fps, clear normalized audio, and captions inset from the right and bottom controls. Low-resolution footage cannot gain real detail by enlarging it.</p><p>TikTok says watch time, full watches, skips and other interactions inform recommendations. These transcript checks are editing advice—not TikTok’s scoring formula or a prediction of views. Review actual retention in TikTok after posting and test different openings.</p><p>Post content you created or have permission to share. Reused material without anything new can be ineligible for the For You feed; caption styling alone does not establish eligibility. Use accurate topic words in your post caption. No hashtag or setting guarantees reach.</p><p><a href="https://support.tiktok.com/en/using-tiktok/exploring-videos/how-tiktok-recommends-content" target="_blank" rel="noopener">TikTok recommendations</a> · <a href="https://www.tiktok.com/community-guidelines/en/integrity-authenticity" target="_blank" rel="noopener">Originality guidance</a> · <a href="https://ads.tiktok.com/resources/help/article/creative-best-practices?lang=en" target="_blank" rel="noopener">Creative advice for ads</a></p><p>The six-second opening check and vertical, captioned presentation draw on TikTok’s ad creative advice; they are not organic ranking requirements.</p>';review.append(details);
};render();


const linksRender=render;render=function(){linksRender();splitControls.hidden=$('clipMode').value!=='whole';};
$('uploadTranscript').hidden=true;

let twitchProject=null;
const originalDownload=document.createElement('a');originalDownload.className='primary batch-export';originalDownload.hidden=true;originalDownload.textContent='Download original Twitch clip ↓';$('importForm').after(originalDownload);
const youtubeAdd=addVideo;
addVideo=async function(url){
 if(processing)throw Error('Wait for the current video to finish.');
 const u=new URL(url),host=u.hostname.toLowerCase();let slug;
 if(host==='clips.twitch.tv')slug=u.pathname.match(/^\/([A-Za-z0-9_-]+)\/?$/)?.[1];
 else if(['twitch.tv','www.twitch.tv','m.twitch.tv'].includes(host))slug=u.pathname.match(/^\/[A-Za-z0-9_]+\/clip\/([A-Za-z0-9_-]+)\/?$/)?.[1];
 twitchProject=null;originalDownload.hidden=true;
 if(!slug)return youtubeAdd(url);
 const health=await requestJSON('/api/health');if(!health.ready)throw Error('Start the video processor using Start-Cutroom, then try again.');
 state={...state,demo:false,videoId:null,clips:[],cues:[],selected:0};projectId=null;$('transcript').value='';$('importError').textContent='';$('analysisError').textContent='';$('sourceScreen').replaceChildren();$('sourceTitle').textContent='Your Twitch clip';$('sourceMeta').textContent='Downloading and reading the clip…';setBusy(true);render();showProgress('Connecting to Twitch…',2);
 try{const job=await requestJSON('/api/analyze',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url})});const result=await pollJob(job.id);projectId=job.id;twitchProject=job.id;state.cues=result.cues;$('transcript').value=toSrt(result.cues);$('sourceTitle').textContent=result.title;$('sourceMeta').textContent=result.method+' · '+stamp(result.duration);originalDownload.href='/api/original/'+job.id+'/download';originalDownload.hidden=false;
 try{findHighlights()}catch{$('clipMode').value='whole';$('partCount').value=1;findHighlights()}
 showProgress('Your Twitch clip is ready',100);$('jobDetail').textContent=result.note||'Download the original immediately, or create a vertical edit below.';showTwitchSource();return {projectId,clips:state.clips.length,provider:'twitch'};
 }catch(e){$('importError').textContent=e.message;showProgress('Could not import Twitch clip',0);throw e}finally{setBusy(false);render()}
};
function showTwitchSource(){if(!twitchProject)return;const c=selected(),v=document.createElement('video');v.controls=true;v.preload='metadata';v.style.cssText='width:100%;height:100%;object-fit:contain';v.src='/api/original/'+twitchProject+'/preview';v.onloadedmetadata=()=>{if(c)v.currentTime=c.start};v.ontimeupdate=()=>{if(c&&v.currentTime>=c.end)v.pause()};$('sourceScreen').replaceChildren(v)}
const providerRender=render;render=function(){providerRender();if(twitchProject){$('sourceBadge').textContent='TWITCH';$('sessionTag').textContent='Twitch project';$('playSelection').disabled=processing||!selected();}};
const providerPreview=$('playSelection').onclick;$('playSelection').onclick=()=>twitchProject?showTwitchSource():providerPreview();
const providerDemo=$('demoBtn').onclick;$('demoBtn').onclick=()=>{twitchProject=null;originalDownload.hidden=true;providerDemo()};

